Method.Implementation:
Set tSC=..setFilePath(pFileDir,.tOldDir)  If $$$ISERR(tSC) { $$$LOGSTATUS(tSC)  Quit 0 }
Set tOK=$S(..%isSFTP:..FTP.DeleteSSH(pFilename),1:..FTP.Delete(pFilename))
Do:'tOK ..disconnectOnNetErr(,1)
If ..Connected { Set tSC=..restoreFilePath(tOldDir)  If $$$ISERR(tSC) $$$LOGSTATUS(tSC)  Quit 0 }
Quit tOK

Set tSC=..setFilePath(pFileDir,.tOldDir)  If $$$ISERR(tSC) { $$$LOGSTATUS(tSC)  Quit 0 }
Set tOK=$S(..%isSFTP:..FTP.RenameSSH(pFilename,pNewFilename),1:..FTP.Rename(pFilename,pNewFilename))
Do:'tOK ..disconnectOnNetErr(,1)
If ..Connected { Set tSC=..restoreFilePath(tOldDir)  If $$$ISERR(tSC) $$$LOGSTATUS(tSC)  Quit 0 }
Quit tOK

$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.OnInit(): Initializing component.")
Set tSC=..testPaths()  Quit:$$$ISERR(tSC) tSC
Do ..EmptyDoneFileTable()
Do ..EmptyErrorFileTable()


Set tStyle = $ZSTRIP($ZCVT(..ServerListStyle,"L"),"*W","-_,;:/")
Set:..%isSFTP tStyle="unix"
Set:"vmsa"=$E(tStyle,1,$L("vmsa")) ..VMSLatestVersionOnly=0
If ""=..FilenameExpression {
	If "msdos"=tStyle {
		// Standard listing style for Windows server in MS-DOS mode
		Set ..FilenameExpression = "$this.spacepiece(%line,4,999)" ; 4th space-delimited piece is the name
		Set ..TimestampExpression = "$this.spacepiece(%line,1,3)" ; include size too - to detect that kind of change also
		Set ..IsDirExpression = "($this.spacepiece(%line,3)=""<DIR>"")"
		Set ..SizeExpression = "$this.spacepiece(%line,3)"
	} Elseif "vms"=tStyle || ("vmsa"=$E(tStyle,1,$L("vmsa"))) {
		// Standard VMS style server listing
		Set ..FilenameExpression = "$this.spacepiece(%line,1)"
		Set ..TimestampExpression = "$this.spacepiece(%line,3,6)"
		Set ..IsDirExpression = "($this.spacepiece(%line,1)["".DIR;"")"
		Set ..SizeExpression = "$piece($this.spacepiece(%line,2),""/"",1)"
	} Elseif "as400"=tStyle {
		// AS/400 / iSeries style server listing
		Set ..FilenameExpression = "$this.spacepiece(%line,6)"
		Set ..TimestampExpression = "$this.spacepiece(%line,1,5)"
		Set ..IsDirExpression = "($ZCVT($this.spacepiece(%line,5),""U"")=""*DIR"")"
		Set ..SizeExpression = "$this.spacepiece(%line,2)"
		If ..ConfirmComplete#2 Set ..ConfirmComplete=$$$XOR(..ConfirmComplete,1)  $$$LOGWARNING("Turning off ConfirmComplete='Size' not allowed for AS400 file 'members'")
	} ElseIf "netware"=tStyle {
		// NetWare listing style
		Set ..FilenameExpression = "$this.spacepiece(%line,8,999)" 
		Set ..TimestampExpression = "$this.spacepiece(%line,1,7)" 
		Set ..IsDirExpression = "(""d""=$E(%line))"
		Set ..SizeExpression = "$this.spacepiece(%line,4)"
	} Else {
		// Standard Unix style server listing
		Set ..FilenameExpression = "$this.spacepiece(%line,9,999)"
		Set ..TimestampExpression = "$this.spacepiece(%line,1,8)"
		Set ..IsDirExpression = "(""d""=$E(%line))"
		Set ..SizeExpression = "$this.spacepiece(%line,5)"
	}
}
Set ..SemaphoreSpec=$ZSTRIP(..SemaphoreSpec,"<>W")
If ..SemaphoreSpec'="" {
	Set tSemaphoreSpec="",tNumberOfSpecs=$L(..SemaphoreSpec,";")
	For c=1:1:tNumberOfSpecs {
		Set tPair=$P(..SemaphoreSpec,";",c),tWarn=0
		If tPair'="" {
			Set tTargetSpec=$P(tPair,"=",1)
			Set:(tTargetSpec="") tTargetSpec="*",tWarn=1
			Set tSemSpec=$P(tPair,"=",2)
			Set:(tSemSpec="") tSemSpec=tTargetSpec,tTargetSpec="*"
			Set:('tWarn&&tTargetSpec'="*") tWarn=tSemSpec=tTargetSpec 
			If tWarn $$$LOGWARNING("Incorrect Semaphore Specification"_" "_..SemaphoreSpec)
			Set tSemaphoreSpec=tSemaphoreSpec_tTargetSpec_"="_tSemSpec_$S(c=tNumberOfSpecs:"",1:";")
		}
	}
	Set ..SemaphoreSpec=tSemaphoreSpec
}
Set:..StayConnected>0&&(..StayConnected<..CallInterval) ..KeepaliveInterval=..StayConnected
Do ..FileListStreamNewObject() $$$ASSERT($IsObject(..FileListStream))
Set ..FileListStream.LineTerminator=$C(13,10)
Do ..FileSizeStreamNewObject() $$$ASSERT($IsObject(..FileSizeStream))
Set ..FileSizeStream.LineTerminator=$c(13,10)

Set ..%CurrResultSet=##class(%ResultSet).%New($$$CurrentClass_":DeepList")  $$$ASSERT($IsObject(..%CurrResultSet))
Kill ..%CurrResultSet.Data
$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.OnInit(): clean up on restart")
Kill $$$EnsRuntimeAppData(..BusinessHost.%ConfigName,"adapter.ftp") ; clean up on restart
Set:"vms"=tStyle&&("*"=..FileSpec) ..FileSpec="*.*" ; force functional wildcard for Search on VMS
If 0=..BusinessHost.%GetParameter("LOGTRANSFERS") Set ..%logTransfers=0

If ..StayConnected<0 { Set tSC=..Connect(..ConnectTimeout,1)  If $$$ISERR(tSC) $$$LOGWARNING($$$StatusDisplayString(tSC)) } // timeout is not fatal at this point, but do log it
Else { $$$SetJobMonitor(..BusinessHost.%ConfigName,$$$SystemName_":"_$Job,$$$eMonitorConnected,"0|"_$$$timeUTC) }
Quit $$$OK

#define ErrorFileTable(%tk) $$$EnsRuntimeAppData(..BusinessHost.%ConfigName,"adapter.ftp",%tk)
#define DoneFileTable(%tk)  $$$EnsStaticAppData(..BusinessHost.%ConfigName,"adapter.ftp",%tk)
	Set FilesRemaining = 1
	Set LoopThresholdCounter = ..LoopThreshold
	Do ..RefreshDirectoryContents()
	Set $ZT="Trap", tSC=$$$OK, (tOneFilename,tFullFilename,tFilename,tTableKey)="", tDone=0
	if ("DELETE"=$ZStrip(..ActionOnSourceFile,"<>W")){  //If we want to delete the source file
		Set ..DeleteFromServer = 1
	}
	else {
		Set ..DeleteFromServer = 0
	}

	Do {
		Set LoopThresholdCounter = LoopThresholdCounter-1

		if (LoopThresholdCounter > 0) 
		{
			Quit:""=..FileSpec

			If '..Connected Set tSC=..Connect(..ConnectTimeout,1)
			Quit:$$$ISERR(tSC)

			$$$catTRACE("connwait","IHC.ITF.Adapter.OnTask() Looking for files '"_..FileSpec_"' in path '"_..FilePath_"'")
			Set tSC=..%CurrResultSet.Execute($this,..FilePath,..FileSpec,..SubdirectoryLevels,$S(..%isSFTP:"FileListSSH",1:"FileList"),..SemaphoreSpec)  Quit:$$$ISERR(tSC)
			Kill ^||Ens.FileInbound.Found,^||Ens.FileInbound.Semaphore

			#; find the next one that can be processed
			For {
				/* 
					Check if the last file needs retrying 
					and use the current row rather than advancing.
				*/
				If ..%LastFileNeedsRetrying {
					$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.OnTask(): Last file needs retrying.")
					Set ..%LastFileNeedsRetrying=0
				} Else {
					If '..%CurrResultSet.Next(.tSC) {//If %CurrResultSet is empty
						$$$TRACE("Done iterating the ResultSet for the current query execution - clean it up")
						#; Done iterating the ResultSet for the current query execution - clean it up
						Do ..%CurrResultSet.Close()

						Kill ..%CurrResultSet.Data ; clean it out so next loop iteration will re-Execute the query
						#; delete the semaphore files used in this cycle
						Set tTableKey=$O(^||Ens.FileInbound.Semaphore(""),1,tSemaphorename)

						Do:'..StayConnected ..Disconnect(1)
						#; Remove errored files from the Error global if they no longer exist, and remove processed files from the Done global if they no longer exist
						Quit:$$$ISERR(tSC) ; if the list failed we don't know if the files are still there

						Quit
					} Else { $$$ASSERT($$$ISOK(tSC)) }
				}	

				Set tOneFilename=..%CurrResultSet.Data("ItemName"), tFullFilename=..%CurrResultSet.Data("Name"), tFileDir=..%CurrResultSet.Data("ItemDir"), tModified=..%CurrResultSet.Data("DateModified"), tSize=..%CurrResultSet.Data("Size"), tSemaphorename=..%CurrResultSet.Data("SemaphoreName")  $$$ASSERT(""'=tOneFilename&&(""'=tFullFilename))
				Set tTableKey = ..getFileSubscript(tFullFilename)
				Set ^||Ens.FileInbound.Found(tTableKey)=tFullFilename

				#;Hash to avoid subscript error from long filename and path

				Lock +$$$ErrorFileTable(tTableKey):0 Else  $$$TRACE("Skipping locked file '"_tTableKey_"'") Continue

				#; Skip the files we have already processed except if they are modified; if they errored only warn once
				If $G($$$DoneFileTable(tTableKey))=tModified If '$G(^(tTableKey,"done"_$E($G($$$ErrorFileTable(tTableKey)),-1))) { Set ^("done")=1 $$$TRACE("Skipping previously processed file '"_tFullFilename_"'") } Lock -$$$ErrorFileTable(tTableKey)  Continue

				If $G($$$ErrorFileTable(tTableKey))=tModified If $G(^(tTableKey,"wrn")) { Kill ^("wrn") $$$TRACE("Skipping previously errored file '"_tFullFilename_"' with timestamp '"_tModified_"'") } Lock -$$$ErrorFileTable(tTableKey) Continue

				If ..VMSLatestVersionOnly && ..%isVMS && ('..IsVMSLatestVersion(tFullFilename)) {
					If '..DeleteFromServer {
						If '$G(^(tTableKey,"ver"_$E($G($$$ErrorFileTable(tTableKey)),-1))) { Set ^("ver")=1  $$$TRACE("Skipping not-latest version of file '"_tFullFilename_"'") } 
					} Else {
						If '..delete(tOneFilename,tFileDir) {
							Do ..disconnectOnNetErr(,1)
							If '$G(^(tTableKey,"ver"_$E($G($$$ErrorFileTable(tTableKey)),-1))) { Set ^("ver")=1 $$$TRACE("Failed to delete not-latest version of file '"_tFullFilename_"' - "_..FTP.ReturnCode_":"_..FTP.ReturnMessage) }
						} Else {
							$$$LOGINFO("Deleted non-latest version of file "_tFullFilename)
							Kill $$$ErrorFileTable(tTableKey)					
						}
					}
					Lock -$$$ErrorFileTable(tTableKey)  Continue
				}

				Set $$$ErrorFileTable(tTableKey)=tModified, ^(tTableKey,"wrn")=1

				Set tFilename=tOneFilename, tOneFilename=""
				$$$TRACE("IHC.ITF.Adapter.InShSftpEbixFeedSched.OnTask() Found a good one: "_tFilename)
				Quit ; found a good one
			}
			Quit:""=tFilename //I think an empty filename at this point means no file was found
			Set HigherPriorityFile = ..HasPriority(tTableKey)
			if (..DirectoryContents.Count() < 1){ // If there is nothing matching the File Spec left in the directory
				$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.OnTask(): No files matching File Spec located in source directory.")
				Set FilesRemaining = 0
			}
			elseif (HigherPriorityFile=""){ // If there are files remaining that match the File Spec, but NOT the ID and Relationship filters
				$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.OnTask(): Files matching File Spec located in source directory, but none will be processed because none match the ID or relationship filename patterns.")
				Set FilesRemaining = 0
			}else {
					Set FilesRemaining = 1 // If we are not done, then we need to keep going
					//if ($Match(tTableKey,"^.*QTC_ID_EXTRACT_.*txt")){ //if this is an ID file
					if ($Match(tTableKey,..IdFilenamePattern)){ //if this is an ID file
						Set tSC=..processFile(tFilename,tModified,tSize,.tDone,tFileDir,tSemaphorename) Quit:$$$ISERR(tSC) //Process the ID file
						$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.OnTask(): Done processing ID file: "_tTableKey_".")
						Set $$$DoneFileTable(tTableKey) = tModified //Add the ID file to the done file list
					}
					elseif ($Match(tTableKey,..RelationshipFilenamePattern)){ //Else if this is a relationship file
						//We match the ID file to the relationship file by using the DATE stamp (the TIME stamps will differ)
						Set FilenameDatestamp = $EXTRACT(tTableKey,$FIND(tTableKey,"EXTRACT_"),*-11) //This is the section of the filename that the ID and relationships have in common.
						If (..HasAMatchingIdFile(FilenameDatestamp)){ //If there is an ID file matching this relationship file in the done file list
							Set tSC=..processFile(tFilename,tModified,tSize,.tDone,tFileDir,tSemaphorename) Quit:$$$ISERR(tSC) // Process the relationship file
							$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.OnTask(): Done processing relationship file: "_tTableKey_".")
							Set $$$DoneFileTable(tTableKey) = tModified //Add the relationship file to the done file list
							Set FilesRemaining = 0
							Kill $$$DoneFileTable(tTableKey) //Remove the relationship file from the done file list
						}
						else {//Else if there is no ID file in the done file list, then we have a relationship file with no ID file
							Set FilesRemaining = 0
							Do ..ItfSendEmailOnError("updatedFailureEmailSubject", ..BusinessHost.%ConfigName_" is required to process ID files before the relationship files; however, we received a relationship file ("_tTableKey_") without a previous ID file. Remove both the ID and Relationship files from the file path ("_..FilePath_") then copy the files back in again and restart the component.")
					}
				}
				else {
					Set $$$DoneFileTable(tTableKey) = tModified //Add the ID file to the done file list	
				}
			}
		}
	} While ((LoopThresholdCounter > -1) && (FilesRemaining = 1))
Exit
	If tDone {
		$$$ASSERT($$$ISOK(tSC))
		If tDone=-1&&..VMSLatestVersionOnly&&..%isVMS {
			#; If deleted on VMS but other VMS versions of the file may exist, suppress messages about them
			Set $$$ErrorFileTable(tTableKey)=""
		} Else {
			//Kill $$$ErrorFileTable(tTableKey)
		}
	} ElseIf $$$ISERR(tSC) {
		Set tErrText=$$$StatusText(tSC)
		Do ..disconnectOnNetErr(tErrText,1)
		#; Don't count it as a file error if it was a network error or retryable
		If ""'=tFilename && ('..Connected || ($$$StatusDisplayString(tSC)["<Ens>ErrFTP" && (tErrText?.E1"="1(1"52"1N,1"4"2N)1PC.E))) { ; retry on timeouts also
			Kill $$$ErrorFileTable(tTableKey)
			$$$TRACE("IHC.ITF.Adapter.InShSftpEbixFeedSched.OnTask(): Setting file to be processed again (%LastFileNeedsRetrying=')")
			Set ..%LastFileNeedsRetrying=1
		}
		Set:..StayConnected&&'..Connected ..%LastNetErr=tErrText
	}
	Lock:""'=tFilename -$$$ErrorFileTable(tTableKey)
	Quit tSC
Trap
	Set $ZT="",tSC=$$$EnsSystemError
	Lock:""'=tFilename -$$$ErrorFileTable(tTableKey)
	Goto Exit

Set FileWithPriority=CurrentFilepath // We will assume the current file has priority until we see otherwise
$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.HasPriority(): Checking "_CurrentFilepath_".")
if $Match($PIECE(CurrentFilepath,"/",*),..IdFilenamePattern){ //If the file we are checking for priority matches the ID file pattern it by definition has priority
	$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.HasPriority(): "_CurrentFilepath_" matches "_..IdFilenamePattern)
	Set FileWithPriority=CurrentFilepath
}
if (""'=FileWithPriority) {
	if $Match($PIECE(CurrentFilepath,"/",*),..RelationshipFilenamePattern){ //If the file we are checking for priority matches the Relationship file pattern we need to check for ID files
		$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.HasPriority: "_CurrentFilepath_" matches "_..RelationshipFilenamePattern)
		for DirectoryContentsCounter=1:1:..DirectoryContents.Count() { // For each filename in the current directory
			Set CurrentFilename = $PIECE(..DirectoryContents.GetAt(DirectoryContentsCounter),"/",*)
			if ($Match(CurrentFilename,..IdFilenamePattern)){ // If we have found an ID file
				Set FileWithPriority=""_..DirectoryContents.GetAt(DirectoryContentsCounter)
			}
		}
	}			
}
Quit FileWithPriority

	$$$TRACE("TraceErrorFileTableContents("_Location_")")
 	Set key = $Order(^Ens.AppData("PAYER",..BusinessHost.%ConfigName,"adapter.ftp",""))
 	While (key '= "")
 	{
    	// Write out contents
    	$$$TRACE(Location_ " ErrorFileTableContents "_key_"="_$G(^CacheTemp.EnsRuntimeAppData("PAYER",..BusinessHost.%ConfigName,"adapter.ftp",key)))
    	// Find next node
    	Set key = $Order(^CacheTemp.EnsRuntimeAppData("PAYER",..BusinessHost.%ConfigName,"adapter.ftp",key))
	}

	$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.HasAMatchingIdFile()")
 	Set MatchingIDFileFound = 0
 	Set key = $Order(^Ens.AppData(..BusinessHost.%ConfigName, "adapter.ftp",""))
 	While (key '= "")
 	{
    	//Check to see if the current entry has the relevent Datestamp
    	Set Regex = ".*QTC_ID_EXTRACT_"_Datestamp_".*"
    	if ($Match(key,Regex)) //if the current entry has the relevent timestamp
    	{
	    	Set MatchingIDFileFound = 1
    	}
    	// Find next node
    	Set key = $Order(^Ens.AppData(..BusinessHost.%ConfigName, "adapter.ftp", key))
	}
	Quit MatchingIDFileFound

	$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.EmptyDoneFileTable()")
 	Set key = $Order(^Ens.AppData(..BusinessHost.%ConfigName, "adapter.ftp",""))
 	While (key '= "")
 	{
    	// Write out contents
    	$$$TRACE(Location_" DoneFileTableContents "_key_"="_$G(^Ens.AppData(..BusinessHost.%ConfigName, "adapter.ftp", key)))
    	// Find next node
    	Set key = $Order(^Ens.AppData(..BusinessHost.%ConfigName, "adapter.ftp", key))
	}

	$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.EmptyErrorFileTable()")
 	Set key = $Order(^Ens.AppData("PAYER",..BusinessHost.%ConfigName,"adapter.ftp",""))
 	While (key '= "")
 	{
	 	Kill ^CacheTemp.EnsRuntimeAppData("PAYER",..BusinessHost.%ConfigName,"adapter.ftp",key)
    	// Find next node
    	Set key = $Order(^CacheTemp.EnsRuntimeAppData("PAYER",..BusinessHost.%ConfigName,"adapter.ftp",key))
	}

	$$$TRACE("IHC.ITF.FTP.Adapter.InShSftpEbixFeedSched.EmptyDoneFileTable()")
 	Set key = $Order(^Ens.AppData(..BusinessHost.%ConfigName, "adapter.ftp",""))
 	While (key '= "")
 	{
	 	Kill ^Ens.AppData(..BusinessHost.%ConfigName, "adapter.ftp", key)
    	// Find next node
    	Set key = $Order(^Ens.AppData(..BusinessHost.%ConfigName, "adapter.ftp", key))
	}
